#!/usr/bin/env python3
"""Money Tracker - prepares the Android build. Run by GitHub Actions (see .github/workflows/android.yml).

  python3 android_setup.py web      copy the app into www/ and switch on the phone-app features
  python3 android_setup.py android  set version, signing, permissions, icons and launch screen
"""
import base64, json, os, re, shutil, sys

def version():
    v = json.load(open('version.json'))['version']
    major, minor = (int(x) for x in v.split('.')[:2])
    return v, major * 100 + minor

def web():
    os.makedirs('www', exist_ok=True)
    for f in ['index.html', 'jszip.min.js', 'manifest.webmanifest', 'icon-192.png', 'icon-512.png', 'apple-touch-icon.png']:
        if os.path.exists(f): shutil.copy(f, 'www/' + f)
    shutil.copy('node_modules/@capacitor/core/dist/capacitor.js', 'www/capacitor.js')
    repo = os.environ.get('GITHUB_REPOSITORY', 'owner/money-tracker')
    owner, name = repo.split('/')
    gh = 'https://github.com/' + repo
    cfg = {'native': True, 'pagesUrl': 'https://%s.github.io/%s/' % (owner.lower(), name),
           'releaseUrl': gh + '/releases/latest', 'apkUrl': gh + '/releases/latest/download/MoneyTracker.apk'}
    open('www/config.js', 'w').write('window.MT_CONFIG = ' + json.dumps(cfg) + ';\n')
    html = open('www/index.html', encoding='utf-8').read()
    if '<!--NATIVE-->' not in html: sys.exit('index.html is missing the <!--NATIVE--> marker - upload the latest index.html')
    html = html.replace('<!--NATIVE-->', '<script src="config.js"></script>\n<script src="capacitor.js"></script>', 1)
    open('www/index.html', 'w', encoding='utf-8').write(html)
    print('www ready for', repo)

def android():
    v, code = version()
    g = 'android/app/build.gradle'
    s = open(g).read()
    s = re.sub(r'versionCode \d+', 'versionCode %d' % code, s)
    s = re.sub(r'versionName "[^"]*"', 'versionName "%s"' % v, s)
    if 'signingConfigs' not in s:
        s = s.replace('    buildTypes {', """    signingConfigs {
        release {
            storeFile file('release.keystore')
            storePassword System.getenv('KEYSTORE_PASSWORD')
            keyAlias 'moneytracker'
            keyPassword System.getenv('KEYSTORE_PASSWORD')
            storeType 'pkcs12'
        }
    }
    buildTypes {""", 1)
        s = s.replace('        release {\n            minifyEnabled false', '        release {\n            signingConfig signingConfigs.release\n            minifyEnabled false', 1)
    assert 'signingConfig signingConfigs.release' in s, 'could not add signing to build.gradle'
    open(g, 'w').write(s)
    m = 'android/app/src/main/AndroidManifest.xml'
    s = open(m).read()
    if 'USE_BIOMETRIC' not in s:
        s = s.replace('</manifest>', '    <uses-permission android:name="android.permission.USE_BIOMETRIC" />\n</manifest>')
    open(m, 'w').write(s)
    res = 'android/app/src/main/res/'
    for path, b64 in ASSETS.items():
        os.makedirs(os.path.dirname(res + path), exist_ok=True)
        open(res + path, 'wb').write(base64.b64decode(b64))
    bg = res + 'values/ic_launcher_background.xml'
    open(bg, 'w').write('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="ic_launcher_background">#0B6E4F</color>\n</resources>\n')
    print('android project ready: version', v, 'code', code)

ASSETS = {"mipmap-mdpi/ic_launcher.png": "", "mipmap-mdpi/ic_launcher_round.png": "", "mipmap-mdpi/ic_launcher_foreground.png": "", "mipmap-hdpi/ic_launcher.png": "", "mipmap-hdpi/ic_launcher_round.png": "", "mipmap-hdpi/ic_launcher_foreground.png": "", "mipmap-xhdpi/ic_launcher.png": "", "mipmap-xhdpi/ic_launcher_round.png": "", "mipmap-xhdpi/ic_launcher_foreground.png": "", "mipmap-xxhdpi/ic_launcher.png": "", "mipmap-xxhdpi/ic_launcher_round.png": "", "mipmap-xxhdpi/ic_launcher_foreground.png": "", "mipmap-xxxhdpi/ic_launcher.png": "", "mipmap-xxxhdpi/ic_launcher_round.png": "", "mipmap-xxxhdpi/ic_launcher_foreground.png": "", "drawable-mdpi/ic_stat_money.png": "", "drawable-hdpi/ic_stat_money.png": "", "drawable-xhdpi/ic_stat_money.png": "", "drawable-xxhdpi/ic_stat_money.png": "", "drawable-xxxhdpi/ic_stat_money.png": "", "drawable/splash.png": "", "drawable-land-mdpi/splash.png": "", "drawable-land-hdpi/splash.png": "", "drawable-land-xhdpi/splash.png": "", "drawable-land-xxhdpi/splash.png": "", "drawable-land-xxxhdpi/splash.png": "", "drawable-port-mdpi/splash.png": "", "drawable-port-hdpi/splash.png": "", "drawable-port-xhdpi/splash.png": "", "drawable-port-xxhdpi/splash.png": "", "drawable-port-xxxhdpi/splash.png": ""}

if __name__ == '__main__':
    {'web': web, 'android': android}[sys.argv[1]]()
